// Canonical host-independent policy. Claude's self-contained copy is generated byte for byte.
const CLAUDE_IDLE_MS = 3000000;
const CODEX_IDLE_MS = 1200000;
const MAX_BUDGET_MS = 14400000;
const INPUT_THRESHOLD = 100000;
const MAX_MESSAGE_CODE_POINTS = 256;

export type WatcherDefaults = { idleMs: number; budgetMs: number; threshold: number };
export type ControlConfiguration = WatcherDefaults & {
  warm: boolean;
  paused: boolean;
  message: string;
  controlRevision: number;
  controlChangedAt: number;
};
export type ConsentState = { freshRequired: boolean; freshAfter: number };
export type WatcherState = {
  userAt: number | null;
  warmAt: number | null;
  busy: boolean;
  generation: number;
  pending: boolean;
  dispatched: boolean;
  sessionId: string;
  turnId: string;
  ended: boolean;
  reservationId: string;
  tokens: number | null;
};
export type WatchEvent = {
  type: string;
  at: number;
  sessionId?: string;
  turnId?: string;
  source?: string;
  config?: WatcherDefaults;
  enabled?: boolean;
  changedAt?: number;
  submittedAt?: number;
  generation?: number;
  observedAt?: number;
  reservationId?: string;
  raw?: unknown;
  [key: string]: unknown;
};
type Decision = { action: string; reason: string };
type TokenMeasurement = {
  context?: { tokens?: number };
  tokenUsage?: { last?: { inputTokens?: number } };
};
type ConstructorConfiguration = Partial<WatcherDefaults> & {
  probeThreshold?: number;
  controlChangedAt?: number;
  paused?: boolean;
};

export const controlKeys: Record<string, string> = {
  idleMs: 'idle_ms',
  budgetMs: 'budget_ms',
  threshold: 'threshold',
  message: 'message',
  paused: 'paused',
  controlRevision: 'control_revision',
  controlChangedAt: 'control_changed_at',
};
const object = (value: unknown): value is Record<string, unknown> =>
  !!value && typeof value === 'object' && !Array.isArray(value);
const providerIdleMs = (provider: string) =>
  provider === 'claude' ? CLAUDE_IDLE_MS : CODEX_IDLE_MS;
const validTimings = (values: number[]) =>
  values.every(value => Number.isSafeInteger(value) && value > 0 && value <= MAX_BUDGET_MS);
const decision = (action: string, reason = ''): Decision => ({ action, reason });

export function claudeControlOptions(document: unknown) {
  if (!object(document)) throw new Error('Invalid Vesta configuration document');
  let container = document;
  for (const key of ['pluginConfigs', 'vesta@vesta-local', 'options']) {
    if (!Object.hasOwn(container, key)) return {};
    const child = container[key];
    if (!object(child)) throw new Error('Invalid Vesta configuration container');
    container = child;
  }
  return container;
}

function validateControlNumbers(config: ControlConfiguration) {
  if (!validTimings([config.idleMs, config.budgetMs]))
    throw new Error('Configuration timings must be integer milliseconds from 1 through 14400000');
  if (
    ![config.threshold, config.controlRevision, config.controlChangedAt].every(
      value => Number.isSafeInteger(value) && value >= 0,
    )
  )
    throw new Error(
      'Configuration threshold/revision/change time must be nonnegative safe integers',
    );
}

function validateControlMessage(message: string) {
  if (
    typeof message !== 'string' ||
    !message.trim() ||
    [...message].length > MAX_MESSAGE_CODE_POINTS ||
    /[\p{Cc}\p{Cs}\u2028\u2029]/u.test(message)
  )
    throw new Error(
      'Configuration message must be a nonempty single line of at most 256 Unicode code points without control characters',
    );
}

export function controlConfig(provider: string, raw: unknown = {}, nativeClaude = false) {
  if (!object(raw)) throw new Error('Invalid Vesta configuration object');
  const get = <Value>(key: string, fallback: Value): Value => {
    const value = raw[nativeClaude ? (controlKeys[key] ?? key) : key];
    return value === undefined ? fallback : (value as Value);
  };
  const config: ControlConfiguration = {
    warm: raw.warm === true,
    paused: get('paused', false),
    idleMs: get('idleMs', providerIdleMs(provider)),
    budgetMs: get('budgetMs', MAX_BUDGET_MS),
    threshold: get('threshold', INPUT_THRESHOLD),
    message: get('message', 'VESTA_CACHE_KEEPALIVE'),
    controlRevision: get('controlRevision', 0),
    controlChangedAt: get('controlChangedAt', 0),
  };
  if (
    (raw.warm !== undefined && typeof raw.warm !== 'boolean') ||
    typeof config.paused !== 'boolean'
  )
    throw new Error('Invalid Vesta configuration boolean');
  validateControlNumbers(config);
  validateControlMessage(config.message);
  return config;
}

function watcherDefaults(provider: string, config: ConstructorConfiguration): WatcherDefaults {
  return {
    idleMs: config.idleMs === undefined ? providerIdleMs(provider) : config.idleMs,
    budgetMs: config.budgetMs === undefined ? MAX_BUDGET_MS : config.budgetMs,
    threshold:
      config.probeThreshold === undefined
        ? (config.threshold ?? INPUT_THRESHOLD)
        : config.probeThreshold,
  };
}

function validateWatcherDefaults(
  defaults: WatcherDefaults,
  config: ConstructorConfiguration,
  mode: string,
) {
  if (!validTimings([defaults.idleMs, defaults.budgetMs]))
    throw new Error('timings must be positive integer milliseconds, at most four hours');
  if (config.probeThreshold !== undefined && mode !== 'probe')
    throw new Error('threshold override requires explicit probe mode');
  if (!Number.isSafeInteger(defaults.threshold) || defaults.threshold < 0)
    throw new Error('invalid threshold');
}

export class Watcher {
  provider: string;
  defaults: WatcherDefaults;
  state: WatcherState = {
    userAt: null,
    warmAt: null,
    busy: false,
    generation: 0,
    pending: false,
    dispatched: false,
    sessionId: '',
    turnId: '',
    ended: false,
    reservationId: '',
    tokens: null,
  };
  private previousAt = -1;
  private serial = 0;
  private reservedGeneration = -1;
  private invalidatedAt = 0;
  private completedGeneration = -1;
  private activeGeneration = -1;
  private freshRequired = false;
  private freshAfter = 0;
  private warmingAllowed = true;

  constructor(provider: string, raw: unknown = {}, mode = 'normal') {
    if (!['claude', 'codex'].includes(provider))
      throw new Error('provider must be claude or codex');
    if (!object(raw)) throw new Error('invalid configuration');
    // Keep the constructor's historical consent coercions; only defaults are validated here.
    const config = raw as ConstructorConfiguration;
    this.provider = provider;
    const defaults = watcherDefaults(provider, config);
    validateWatcherDefaults(defaults, config, mode);
    this.defaults = defaults;
    this.freshAfter = config.controlChangedAt ?? 0;
    this.warmingAllowed = config.paused !== true;
    this.freshRequired = this.freshAfter > 0 || !this.warmingAllowed;
  }

  activeTurnEligible() {
    return this.state.busy && this.activeGeneration === this.state.generation;
  }

  consentState(): ConsentState {
    return { freshRequired: this.freshRequired, freshAfter: this.freshAfter };
  }

  restoreConsent(raw: unknown) {
    const value = raw as ConsentState | null | undefined;
    if (
      typeof value?.freshRequired !== 'boolean' ||
      !Number.isSafeInteger(value.freshAfter) ||
      value.freshAfter < this.freshAfter
    )
      return;
    this.freshRequired = value.freshRequired;
    this.freshAfter = value.freshAfter;
  }

  event(event: WatchEvent) {
    if (!Number.isSafeInteger(event.at) || event.at < 0 || event.at < this.previousAt)
      throw new Error('event timestamps must be monotonic nonnegative safe integers');
    this.previousAt = event.at;
    // Preserve gate precedence, including owner checks before ended/control handling.
    const result =
      this.ownerDecision(event) ??
      this.lifecycleDecision(event) ??
      this.contextDecision(event) ??
      this.completionDecision(event) ??
      this.measurementDecision(event) ??
      this.submissionDecision(event);
    return { type: event.type, at: event.at, ...result, state: { ...this.state } };
  }

  private ownerDecision(event: WatchEvent): Decision | undefined {
    if (
      ['turn-start', 'turn-complete', 'measure'].includes(event.type) &&
      ![event.sessionId, event.turnId].every(id => typeof id === 'string' && id.length > 0)
    )
      return decision('skip', 'invalid owner binding');
    const foreign =
      event.sessionId && this.state.sessionId && event.sessionId !== this.state.sessionId;
    if (foreign) return decision('skip', 'foreign owner');
    if (this.state.ended) return decision('ended', 'owner ended');
  }

  private lifecycleDecision(event: WatchEvent): Decision | undefined {
    const state = this.state;
    if (event.type === 'exit') {
      state.ended = true;
      state.pending = false;
      return decision('ended');
    }
    if (event.type === 'control') return this.controlDecision(event);
    if (event.type !== 'activity') return;
    if (event.source !== 'user') return decision('skip', 'not verified user activity');
    const pending = state.pending;
    state.userAt = event.at;
    state.pending = false;
    return decision(pending ? 'cancel' : 'observe', 'user activity');
  }

  private controlDecision(event: WatchEvent): Decision {
    if (event.config)
      this.defaults = {
        idleMs: event.config.idleMs,
        budgetMs: event.config.budgetMs,
        threshold: event.config.threshold,
      };
    this.warmingAllowed = event.enabled === true;
    this.freshAfter = Math.max(this.freshAfter, event.changedAt ?? event.at);
    this.freshRequired = true;
    this.state.pending = false;
    this.state.tokens = null;
    this.state.generation++;
    this.invalidatedAt = event.at;
    this.completedGeneration = -1;
    this.activeGeneration = -1;
    return decision('cancel', 'configuration changed; fresh user prompt and reply required');
  }

  private contextDecision(event: WatchEvent): Decision | undefined {
    if (!['compact', 'reconnect', 'interrupt', 'turn-start'].includes(event.type)) return;
    if (event.type === 'turn-start' && (!event.sessionId || !event.turnId))
      return decision('skip', 'missing owner binding');
    const state = this.state;
    const pending = state.pending;
    const active = this.activeTurnEligible();
    state.pending = false;
    state.tokens = null;
    state.generation += 1;
    this.invalidatedAt = event.at;
    this.completedGeneration = -1;
    this.activeGeneration = -1;
    if (event.type === 'interrupt') state.busy = false;
    else if (event.type !== 'turn-start' && this.canResumeActiveTurn(active))
      this.activeGeneration = state.generation;
    if (event.type === 'turn-start') this.startTurn(event);
    return decision(pending ? 'cancel' : 'observe', 'context invalidated');
  }

  private canResumeActiveTurn(active: boolean) {
    return active && !this.freshRequired && this.warmingAllowed;
  }

  private startTurn(event: WatchEvent) {
    this.state.sessionId = event.sessionId!;
    this.state.turnId = event.turnId!;
    this.state.busy = true;
    const fresh =
      event.source === 'user' &&
      Number.isSafeInteger(event.submittedAt) &&
      event.submittedAt! >= this.freshAfter;
    if (this.warmingAllowed && (!this.freshRequired || fresh)) {
      this.activeGeneration = this.state.generation;
      this.freshRequired = false;
    }
  }

  private completionDecision(event: WatchEvent): Decision | undefined {
    if (event.type !== 'turn-complete') return;
    const state = this.state;
    if (event.sessionId !== state.sessionId || event.turnId !== state.turnId || !state.busy)
      return decision('skip', 'stale completed turn');
    if (this.activeGeneration !== state.generation) {
      state.busy = false;
      state.dispatched = false;
      state.warmAt = event.at;
      state.tokens = null;
      return decision('observe', 'invalidated turn finished; fresh response still required');
    }
    state.busy = false;
    state.dispatched = false;
    state.warmAt = event.at;
    this.completedGeneration = state.generation;
    state.tokens = this.tokens(event.raw);
    return decision('observe', 'completed response');
  }

  private measurementDecision(event: WatchEvent): Decision | undefined {
    if (event.type !== 'measure') return;
    const state = this.state;
    if (
      this.measurementOwnerMismatch(event) ||
      !Number.isSafeInteger(event.observedAt) ||
      event.observedAt! > event.at ||
      event.observedAt! < Math.max(this.invalidatedAt, state.warmAt ?? event.at) ||
      state.busy
    )
      return decision('skip', 'stale measurement');
    state.tokens = this.tokens(event.raw);
    return decision('observe', 'current input measurement');
  }

  private measurementOwnerMismatch(event: WatchEvent) {
    return (
      event.sessionId !== this.state.sessionId ||
      event.turnId !== this.state.turnId ||
      event.generation !== this.state.generation ||
      this.completedGeneration !== this.state.generation
    );
  }

  private submissionDecision(event: WatchEvent): Decision {
    if (event.type === 'submit-failed') {
      this.state.pending = false;
      this.state.dispatched = false;
      this.state.warmAt = event.at;
      return decision('observe', 'submission failed; cooldown');
    }
    if (event.type !== 'tick' && event.type !== 'dispatch')
      return decision('skip', 'unknown event');
    return this.eligibilityDecision(event) ?? this.reservationDecision(event);
  }

  private eligibilityDecision(event: WatchEvent): Decision | undefined {
    const state = this.state;
    if (state.userAt !== null && event.at - state.userAt >= this.defaults.budgetMs) {
      state.pending = false;
      return decision('expired', 'user inactivity budget exhausted');
    }
    if (!this.warmingAllowed) {
      state.pending = false;
      return decision('skip', 'warming paused or configuration unavailable');
    }
    if (state.busy) {
      state.pending = false;
      return decision('busy', 'owner busy');
    }
    return this.inputEligibilityDecision(event);
  }

  private inputEligibilityDecision(event: WatchEvent): Decision | undefined {
    const state = this.state;
    if (
      state.userAt === null ||
      state.tokens === null ||
      state.tokens <= this.defaults.threshold ||
      !state.sessionId ||
      !state.turnId
    ) {
      state.pending = false;
      return decision('skip', 'unknown or ineligible current input');
    }
    // Idle restarts on the later of a completion and verified user activity, so an owner
    // returning after an expired window is not warmed mid-typing.
    const idleStartedAt = state.warmAt === null ? null : Math.max(state.userAt, state.warmAt);
    if (idleStartedAt === null || event.at - idleStartedAt < this.defaults.idleMs)
      return decision('skip', 'idle interval not elapsed');
  }

  private reservationDecision(event: WatchEvent): Decision {
    const state = this.state;
    if (event.type === 'dispatch') {
      if (
        !state.pending ||
        state.dispatched ||
        this.reservedGeneration !== state.generation ||
        (event.reservationId !== undefined && event.reservationId !== state.reservationId)
      )
        return decision('skip', 'no matching pending reservation');
      state.pending = false;
      state.dispatched = true;
      return decision('dispatch', 'committed to native submission; removal not guaranteed');
    }
    if (state.pending || state.dispatched)
      return decision('skip', 'warm already pending or dispatched');
    state.pending = true;
    this.reservedGeneration = state.generation;
    state.reservationId = state.generation + ':' + ++this.serial;
    return decision('reserve', 'eligible idle owner');
  }

  private tokens(raw: unknown): number | null {
    const measurement = raw as TokenMeasurement | null | undefined;
    const value =
      this.provider === 'claude'
        ? measurement?.context?.tokens
        : measurement?.tokenUsage?.last?.inputTokens;
    return Number.isSafeInteger(value) && value! >= 0 ? value! : null;
  }
}
